void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096;
    int phase_rand = rand() % 100;
    if (phase_rand < 60) { // 60% chance: use current trail phases
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) saved[i] = value[i]; // use current assignment
            else saved[i] = local_best[i]; // fallback to local best
        }
    } else if (phase_rand < 80) { // 20% chance: invert local best
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 95) { // 15% chance: random polarity
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else { // 5% chance: clear saved phases
        for (int i = 1; i <= vars; i++) saved[i] = 0;
    }
}
